    """Parse the block-list / dict / inline-list YAML subset used by access.yaml."""
    lines = []
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        lines.append((len(line) - len(line.lstrip()), line.strip()))

    pos = 0

    def parse(ind, in_list):
        nonlocal pos
        result = [] if in_list else {}
        while pos < len(lines):
            lind, txt = lines[pos]
            if lind < ind:
                break
            if txt.startswith("- "):
                pos += 1
                item = {}
                key, _, val = txt[2:].partition(":")
                val = val.strip()
                item[key] = _parse_inline_list(val) if val.startswith("[") else (
                    _parse_scalar(val) if val else None
                )
                result.append(item)
                # continuation keys of this item sit at a deeper indent
                while (
                    pos < len(lines)
                    and lines[pos][0] > lind
                    and not lines[pos][1].startswith("- ")
                ):
                    cont = lines[pos][1]
                    pos += 1
                    k, _, v = cont.partition(":")
                    v = v.strip()
                    item[k] = _parse_inline_list(v) if v.startswith("[") else _parse_scalar(v)
            else:
                pos += 1
                key, _, val = txt.partition(":")
                val = val.strip()
                if val:
                    result[key] = _parse_scalar(val)
                elif pos < len(lines) and lines[pos][0] > ind:
                    result[key] = parse(lines[pos][0], lines[pos][1].startswith("- "))
                else:
                    result[key] = None
        return result

    return parse(0, False)"}]})
